<?php
require_once __DIR__ . '/../config/config.php';require_once __DIR__ . '/../includes/session.php';require_once __DIR__ . '/../includes/auth.php';require_login();require_module_access($conn,'maternity','view');
$canCreate=can_module_action($conn,'maternity','create');if(empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32));$csrfToken=$_SESSION['csrf_token'];$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!$canCreate){http_response_code(403);exit('You do not have permission to record deliveries.');}if(!hash_equals($csrfToken,(string)($_POST['csrf_token']??''))){$error='Security token mismatch.';}else{$conn->begin_transaction();try{$mid=(int)($_POST['maternity_id']??0);$time=trim((string)($_POST['delivery_time']??''));$mode=trim((string)($_POST['delivery_mode']??'SVD'));$doctor=trim((string)($_POST['primary_doctor']??''));$condition=trim((string)($_POST['mother_condition']??''));$comp=trim((string)($_POST['complications']??''));$loss=trim((string)($_POST['blood_loss']??''));$notes=trim((string)($_POST['notes']??''));$babyNo=trim((string)($_POST['baby_number']??'1'));$weight=trim((string)($_POST['baby_weight']??''));$apgar=trim((string)($_POST['apgar']??''));$resusc=trim((string)($_POST['resuscitation']??'None'));$gender=trim((string)($_POST['gender']??'Male'));$alive=(int)($_POST['alive']??1);if($mid<=0||$time==='')throw new Exception('Patient and delivery date/time are required.');$s=$conn->prepare("INSERT INTO maternity_delivery (maternity_id,delivery_time,delivery_mode,primary_doctor,mother_condition,complications,blood_loss,notes,created_at) VALUES (?,?,?,?,?,?,?,?,NOW())");if(!$s)throw new Exception($conn->error);$s->bind_param('isssssss',$mid,$time,$mode,$doctor,$condition,$comp,$loss,$notes);if(!$s->execute())throw new Exception($s->error);$s->close();$b=$conn->prepare("INSERT INTO maternity_baby (maternity_id,baby_number,gender,weight,apgar,resuscitation,notes,created_at,alive) VALUES (?,?,?,?,?,?,?,NOW(),?)");if(!$b)throw new Exception($conn->error);$b->bind_param('issssssi',$mid,$babyNo,$gender,$weight,$apgar,$resusc,$notes,$alive);if(!$b->execute())throw new Exception($b->error);$b->close();if(function_exists('audit'))audit('maternity_delivery',"maternity_id={$mid},mode={$mode}");$conn->commit();header('Location: deliveries.php?saved=1');exit;}catch(Throwable $e){$conn->rollback();$error=$e->getMessage();}}}
$matList=$conn->query("SELECT m.id,p.full_name,p.patient_number,m.anc_number FROM maternity m JOIN patients p ON p.id=m.patient_id ORDER BY p.full_name ASC");
$deliveries=$conn->query("SELECT d.*,b.weight baby_weight,b.apgar,b.gender,b.alive,b.resuscitation,b.baby_number,p.full_name,m.anc_number FROM maternity_delivery d JOIN maternity m ON m.id=d.maternity_id JOIN patients p ON p.id=m.patient_id LEFT JOIN maternity_baby b ON b.maternity_id=m.id AND b.created_at>=d.created_at ORDER BY d.created_at DESC LIMIT 200");
$stats=$conn->query("SELECT COUNT(*) total,SUM(delivery_mode='CS') cs_count,(SELECT COUNT(*) FROM maternity_baby WHERE alive=1) live_births FROM maternity_delivery")->fetch_assoc();
include __DIR__ . '/../includes/header.php';include __DIR__ . '/../includes/sidebar.php';?>
<div class="main-content"><div class="container-fluid pt-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><h2 class="h4 mb-1 text-gray-800"><i class="fas fa-baby text-primary mr-2"></i>Delivery Register</h2><p class="text-muted mb-0">Record deliveries and newborn details in the maternity clinical record.</p></div><a href="index.php" class="btn btn-light">Maternity Dashboard</a></div>
<?php if(isset($_GET['saved'])):?><div class="alert alert-success">Delivery and newborn record saved successfully.</div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?>
<div class="row mb-4"><div class="col-md-4"><div class="card shadow-sm"><div class="card-body"><small class="text-muted">Total Deliveries</small><div class="h4 mb-0"><?= (int)($stats['total']??0) ?></div></div></div></div><div class="col-md-4"><div class="card shadow-sm"><div class="card-body"><small class="text-muted">Live Births</small><div class="h4 mb-0"><?= (int)($stats['live_births']??0) ?></div></div></div></div><div class="col-md-4"><div class="card shadow-sm"><div class="card-body"><small class="text-muted">C-Sections</small><div class="h4 mb-0"><?= (int)($stats['cs_count']??0) ?></div></div></div></div></div>
<?php if($canCreate):?><div class="card shadow-sm mb-4"><div class="card-header bg-white"><strong>Record New Delivery</strong></div><div class="card-body"><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrfToken)?>"><div class="row"><div class="col-md-6 form-group"><label>Patient (ANC Record)</label><select name="maternity_id" class="form-control" required><option value="">Select patient</option><?php if($matList):while($m=$matList->fetch_assoc()):?><option value="<?=$m['id']?>"><?=htmlspecialchars($m['full_name'])?> — <?=htmlspecialchars($m['patient_number'])?> (<?=htmlspecialchars($m['anc_number'])?>)</option><?php endwhile;endif;?></select></div><div class="col-md-3 form-group"><label>Delivery Mode</label><select name="delivery_mode" class="form-control"><option value="SVD">Normal (SVD)</option><option value="CS">Cesarean Section</option><option value="Vacuum">Vacuum</option></select></div><div class="col-md-3 form-group"><label>Date / Time</label><input type="datetime-local" name="delivery_time" class="form-control" required value="<?=date('Y-m-d\TH:i')?>"></div><div class="col-md-4 form-group"><label>Primary Doctor</label><input name="primary_doctor" class="form-control"></div><div class="col-md-4 form-group"><label>Mother Condition</label><input name="mother_condition" class="form-control"></div><div class="col-md-4 form-group"><label>Blood Loss (ml)</label><input name="blood_loss" class="form-control"></div><div class="col-md-4 form-group"><label>Complications</label><input name="complications" class="form-control"></div><div class="col-md-8 form-group"><label>Clinical Notes</label><input name="notes" class="form-control"></div></div><hr><h6 class="text-primary font-weight-bold">Newborn Information</h6><div class="row"><div class="col-md-2 form-group"><label>Baby No.</label><input name="baby_number" class="form-control" value="1"></div><div class="col-md-2 form-group"><label>Gender</label><select name="gender" class="form-control"><option>Male</option><option>Female</option></select></div><div class="col-md-2 form-group"><label>Weight (kg)</label><input name="baby_weight" type="number" step="0.01" min="0" class="form-control"></div><div class="col-md-2 form-group"><label>APGAR</label><input name="apgar" class="form-control" placeholder="9/10"></div><div class="col-md-2 form-group"><label>Resuscitation</label><select name="resuscitation" class="form-control"><option>None</option><option>Oxygen</option><option>Bag & Mask</option><option>Drugs</option></select></div><div class="col-md-2 form-group"><label>Outcome</label><select name="alive" class="form-control"><option value="1">Live Birth</option><option value="0">Stillbirth</option></select></div></div><button class="btn btn-primary"><i class="fas fa-save mr-1"></i>Save Delivery</button></form></div></div><?php endif;?>
<div class="card shadow-sm"><div class="card-header bg-white"><strong>Recent Deliveries</strong></div><div class="card-body p-0"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Date</th><th>Mother</th><th>Mode</th><th>Baby</th><th>APGAR</th><th>Outcome</th><th>Maternal Condition</th></tr></thead><tbody><?php if($deliveries&&$deliveries->num_rows):while($d=$deliveries->fetch_assoc()):?><tr><td><?=htmlspecialchars(date('d M Y H:i',strtotime($d['delivery_time']??$d['created_at'])))?></td><td><strong><?=htmlspecialchars($d['full_name'])?></strong><br><small><?=htmlspecialchars($d['anc_number'])?></small></td><td><?=htmlspecialchars($d['delivery_mode'])?></td><td><?=htmlspecialchars((string)$d['baby_weight'])?> kg · <?=htmlspecialchars($d['gender']??'')?></td><td><?=htmlspecialchars($d['apgar']??'')?></td><td><span class="badge badge-<?=!empty($d['alive'])?'success':'danger'?>"><?=!empty($d['alive'])?'Live Birth':'Stillbirth'?></span></td><td><?=htmlspecialchars($d['mother_condition']??'')?><?php if(!empty($d['complications'])):?><br><small class="text-danger"><?=htmlspecialchars($d['complications'])?></small><?php endif;?></td></tr><?php endwhile;else:?><tr><td colspan="7" class="text-center text-muted py-4">No delivery records found.</td></tr><?php endif;?></tbody></table></div></div></div>
</div></div><?php include __DIR__ . '/../includes/footer.php'; ?>